// WP-08 .docx round-trip harness (AD-2, R10 proof). Fixture documents are
// generated by an INDEPENDENT writer (python3 zipfile, a child process that
// shares nothing with engine/author/docx.mjs), and annotated output is
// verified both by our own reader and by an independent unzip (python3).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { unzip, zip, makeEntry, inflateEntry, readDocx, annotate, crc32, decodeXml } from '../engine/author/docx.mjs';
import { repo, baseRow, vrow, makeRoot } from './_author-fixtures.mjs';

const checkCli = join(repo, 'engine', 'author', 'check.mjs');
const makeDocxPy = join(repo, 'tests', 'fixtures', 'make_docx.py');

const cleanup = [];
process.on('exit', () => {
  for (const d of cleanup) {
    try {
      rmSync(d, { recursive: true, force: true });
    } catch {
      // best effort
    }
  }
});
const tmp = () => {
  const d = mkdtempSync(join(tmpdir(), 'wp08-docx-'));
  cleanup.push(d);
  return d;
};

const python = spawnSync('python3', ['--version'], { encoding: 'utf8' }).status === 0;
const skipPy = !python && 'python3 not available — independent fixture writer cannot run';

// Independent fixture writer: python3 zipfile, spec on stdin.
function makeDocx(spec) {
  const r = spawnSync('python3', ['-I', makeDocxPy], { input: JSON.stringify(spec), encoding: 'utf8' });
  assert.equal(r.status, 0, `fixture writer failed: ${r.stderr}`);
  return readFileSync(spec.out);
}

// Independent verification: python3 unzips and inspects an annotated file.
const VERIFY_PY = `
import json, re, sys, zipfile
from xml.dom import minidom
z = zipfile.ZipFile(sys.argv[1])
doc = z.read('word/document.xml').decode('utf-8')
minidom.parseString(doc)
paras = re.findall(r'<w:p[ >].*?</w:p>', doc, re.S)
def unesc(t):
    for a, b in (('&lt;', '<'), ('&gt;', '>'), ('&quot;', '"'), ('&apos;', "'"), ('&amp;', '&')):
        t = t.replace(a, b)
    return t
texts = [unesc(''.join(re.findall(r'<w:t[^>]*>(.*?)</w:t>', p, re.S))) for p in paras]
comments, authors, dates, bodies = 0, [], [], []
if 'word/comments.xml' in z.namelist():
    cx = z.read('word/comments.xml').decode('utf-8')
    minidom.parseString(cx)
    comments = len(re.findall(r'<w:comment ', cx))
    authors = sorted(set(re.findall(r'w:author="([^"]*)"', cx)))
    dates = sorted(set(re.findall(r'w:date="([^"]*)"', cx)))
    bodies = [unesc(t) for t in re.findall(r'<w:t[^>]*>(.*?)</w:t>', cx, re.S)]
rels = z.read('word/_rels/document.xml.rels').decode('utf-8') if 'word/_rels/document.xml.rels' in z.namelist() else ''
ct = z.read('[Content_Types].xml').decode('utf-8')
print(json.dumps({
    'bad_entry': z.testzip(), 'names': sorted(z.namelist()), 'texts': texts,
    'comments': comments, 'authors': authors, 'dates': dates, 'bodies': bodies,
    'range_starts': len(re.findall(r'<w:commentRangeStart ', doc)),
    'range_ends': len(re.findall(r'<w:commentRangeEnd ', doc)),
    'refs': len(re.findall(r'<w:commentReference ', doc)),
    'rels_has_comments': 'relationships/comments' in rels,
    'ct_has_comments': 'word/comments.xml' in ct,
}))
`;
function pyVerify(path) {
  const r = spawnSync('python3', ['-I', '-c', VERIFY_PY, path], { encoding: 'utf8' });
  assert.equal(r.status, 0, `python verification failed: ${r.stderr}`);
  return JSON.parse(r.stdout);
}

function runCli(args) {
  return spawnSync(process.execPath, [checkCli, ...args], { encoding: 'utf8' });
}

// ---------------------------------------------------------------- zip unit
test('zip writer/reader round-trips and python validates the CRCs', { skip: skipPy }, () => {
  const entries = [
    makeEntry('a.txt', 'alpha contents\n', { date: 0x21 }),
    makeEntry('dir/b.xml', '<x>beta &amp; gamma</x>', { date: 0x21 }),
  ];
  const buf = zip(entries);
  const back = unzip(buf);
  assert.deepEqual(
    back.map((e) => e.name),
    ['a.txt', 'dir/b.xml'],
  );
  assert.equal(inflateEntry(back[0]).toString(), 'alpha contents\n');
  assert.equal(inflateEntry(back[1]).toString(), '<x>beta &amp; gamma</x>');
  // independent read (python checks each CRC on extraction)
  const dir = tmp();
  const p = join(dir, 'roundtrip.zip');
  writeFileSync(p, buf);
  const r = spawnSync(
    'python3',
    ['-I', '-c', "import sys,zipfile\nz=zipfile.ZipFile(sys.argv[1])\nprint(z.testzip())\nprint(z.read('a.txt').decode())", p],
    { encoding: 'utf8' },
  );
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /^None\nalpha contents\n/);
});

test('crc32 matches the known check value', () => {
  // CRC-32 of the ASCII string "123456789" is the classic check constant.
  assert.equal(crc32(Buffer.from('123456789')).toString(16), 'cbf43926');
});

test('xml entity decoding covers named and numeric entities', () => {
  assert.equal(decodeXml('a&amp;b&lt;c&gt;d&#x27e6;e&#65;'), 'a&b<c>d⟦eA');
});

// ------------------------------------------------- reader: python-made docx
test('reader extracts paragraph text in document order, across fragmented runs', { skip: skipPy }, () => {
  const dir = tmp();
  const out = join(dir, 'frag.docx');
  const paragraphs = ['First sentence here. Second one.', 'A token ⟦zza:plan-3.0#p2⟧ split across runs.'];
  makeDocx({ out, paragraphs, chunk: 5 }); // every 5 chars -> its own w:r
  const { paragraphs: got } = readDocx(readFileSync(out));
  assert.deepEqual(
    got.map((p) => p.text),
    paragraphs,
  );
  assert.ok(got[1].runs.length > 5, 'fixture really fragments runs');
});

// --------------------------------------------------------- CLI, live build
const liveReady = existsSync(join(repo, 'data', 'views', 'countries'));
const skipLive = (!liveReady && 'data/views not generated') || skipPy;

// One fixture draft reused across the CLI tests: a real receipt citation
// (picked from the live views the same way the demo page picks its receipt),
// a numeric uncited sentence, a plain uncited sentence, a broken citation.
function livePick() {
  const files = JSON.parse(readFileSync(join(repo, 'data', 'views', 'index.json'), 'utf8')).countries;
  for (const c of files) {
    const view = JSON.parse(readFileSync(join(repo, 'data', 'views', 'countries', `${c.iso3.toLowerCase()}.json`), 'utf8'));
    const row = view.rows.find((r) => r.quote && r.sha256);
    if (row) return { iso3: c.iso3.toLowerCase(), doc_id: row.doc_id };
  }
  throw new Error('no quoted, hashed receipt in the live views');
}

function makeDraft(dir) {
  const { iso3, doc_id } = livePick();
  const out = join(dir, 'draft.docx');
  const paragraphs = [
    `The treaty standing is on record ⟦${iso3}:${doc_id}⟧. The figure 42 has no receipt.`,
    'Nothing cited in this one.',
    'A broken citation ⟦qqz:not-a-receipt⟧ sits here.',
  ];
  makeDocx({ out, paragraphs, chunk: 7 });
  return { out, paragraphs, iso3, doc_id };
}

test('CLI (a): same input twice -> byte-identical annotated .docx and identical JSON', { skip: skipLive }, () => {
  const dir = tmp();
  const { out } = makeDraft(dir);
  const args = (n) => ['--in', out, '--out', join(dir, `ann${n}.docx`), '--json', join(dir, `rep${n}.json`), '--root', repo];
  assert.equal(runCli(args(1)).status, 0);
  assert.equal(runCli(args(2)).status, 0);
  assert.ok(readFileSync(join(dir, 'ann1.docx')).equals(readFileSync(join(dir, 'ann2.docx'))), 'annotated bytes identical');
  assert.equal(readFileSync(join(dir, 'rep1.json'), 'utf8'), readFileSync(join(dir, 'rep2.json'), 'utf8'));
});

test('CLI (b,c,e): verdicts and flags land in the JSON report with deep links', { skip: skipLive }, () => {
  const dir = tmp();
  const { out, iso3, doc_id } = makeDraft(dir);
  const rep = join(dir, 'report.json');
  const r = runCli(['--in', out, '--out', join(dir, 'ann.docx'), '--json', rep, '--root', repo]);
  assert.equal(r.status, 0, r.stderr);
  const report = JSON.parse(readFileSync(rep, 'utf8'));
  assert.equal(report.status, 'ok');
  const cits = report.sentences.flatMap((s) => s.citations);
  const anchored = cits.find((c) => c.doc_id === doc_id);
  assert.equal(anchored.verdict, 'ANCHORED'); // (b) real receipt
  assert.equal(anchored.receipt_url, `/receipt/${iso3}/${doc_id}/`);
  const broken = cits.find((c) => c.doc_id === 'not-a-receipt');
  assert.equal(broken.verdict, 'UNSUPPORTED'); // (c) pointing nowhere
  const numeric = report.sentences.find((s) => s.flags.includes('UNANCHORED-NUMERIC')); // (e)
  assert.match(numeric.text, /figure 42/);
  assert.ok(report.counts.unanchored >= 2);
  assert.equal(typeof report.build_id, 'string');
  assert.equal(typeof report.staleness.stale_fraction, 'number');
});

test('CLI (f): annotated output reopens in our reader AND an independent unzip; text byte-unchanged', { skip: skipLive }, () => {
  const dir = tmp();
  const { out, paragraphs } = makeDraft(dir);
  const ann = join(dir, 'ann.docx');
  assert.equal(runCli(['--in', out, '--out', ann, '--json', join(dir, 'rep.json'), '--root', repo]).status, 0);

  // our own reader half
  const ours = readDocx(readFileSync(ann));
  assert.deepEqual(
    ours.paragraphs.map((p) => p.text),
    paragraphs,
    'document text unchanged through annotation',
  );

  // independent unzip + XML well-formedness (python3 zipfile + minidom)
  const v = pyVerify(ann);
  assert.equal(v.bad_entry, null, 'every entry CRC-valid');
  assert.deepEqual(v.texts, paragraphs, 'independent extraction sees the same unchanged text');
  assert.ok(v.comments >= 3, 'comment layer present (verdicts + numeric flag)');
  assert.deepEqual(v.authors, ['Record Runtime']);
  assert.equal(v.range_starts, v.comments);
  assert.equal(v.range_ends, v.comments);
  assert.equal(v.refs, v.comments);
  assert.ok(v.rels_has_comments, 'comments relationship added');
  assert.ok(v.ct_has_comments, 'content-type override added');
  const report = JSON.parse(readFileSync(join(dir, 'rep.json'), 'utf8'));
  assert.deepEqual(v.dates, [`${report.as_of}T00:00:00Z`], 'w:date is the build as_of, never the wall clock');
  assert.ok(v.bodies.some((b) => b.includes('ANCHORED') && b.includes(`build ${report.build_id}`)));
});

test('CLI (f): a draft without document.xml.rels gains the comments relationship', { skip: skipLive }, () => {
  const dir = tmp();
  const out = join(dir, 'norels.docx');
  const { iso3, doc_id } = livePick();
  makeDocx({ out, paragraphs: [`Cited ⟦${iso3}:${doc_id}⟧.`], no_rels: true });
  const ann = join(dir, 'ann.docx');
  assert.equal(runCli(['--in', out, '--out', ann, '--root', repo]).status, 0);
  const v = pyVerify(ann);
  assert.ok(v.names.includes('word/_rels/document.xml.rels'));
  assert.ok(v.rels_has_comments);
});

test('CLI: --text mode checks a plain-text draft (demo path)', { skip: skipLive }, () => {
  const dir = tmp();
  const { iso3, doc_id } = livePick();
  const draft = join(dir, 'draft.txt');
  writeFileSync(draft, `On the record [[anchor:${iso3}:${doc_id}]].\nThe share is 42 percent.\n`);
  const rep = join(dir, 'report.json');
  const r = runCli(['--text', draft, '--json', rep, '--root', repo]);
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /ANCHORED/);
  assert.match(r.stdout, /UNANCHORED\+UNANCHORED-NUMERIC/);
  const report = JSON.parse(readFileSync(rep, 'utf8'));
  assert.equal(report.sentences[0].citations[0].verdict, 'ANCHORED');
});

// ------------------------------------------------------ AD-12 through the CLI
test('CLI (g): a stale graph refuses to annotate — exit 2, numbers in the report, no output file', { skip: skipPy }, () => {
  const staleRoot = makeRoot({
    cleanup,
    baseRows: [
      baseRow({ record_key: 'k.s1', retrieved_at: '2025-12-01T00:00:00.000Z' }),
      baseRow({ record_key: 'k.s2', retrieved_at: '2025-12-01T00:00:00.000Z' }),
      baseRow({ record_key: 'k.f1', retrieved_at: '2026-01-30T00:00:00.000Z' }),
    ],
    views: { ZZA: [vrow({ doc_id: 'plan-new', sha256: 'b'.repeat(64) })] },
  });
  const dir = tmp();
  const out = join(dir, 'draft.docx');
  makeDocx({ out, paragraphs: ['Cited ⟦zza:plan-new⟧.'] });
  const ann = join(dir, 'ann.docx');
  const rep = join(dir, 'rep.json');
  const r = runCli(['--in', out, '--out', ann, '--json', rep, '--root', staleRoot]);
  assert.equal(r.status, 2, `expected refusal, got ${r.status}: ${r.stdout}${r.stderr}`);
  assert.match(r.stderr, /verification-unavailable/);
  assert.equal(existsSync(ann), false, 'no annotated output against a stale graph');
  const report = JSON.parse(readFileSync(rep, 'utf8'));
  assert.equal(report.status, 'verification-unavailable');
  assert.equal(report.staleness.stale_rows, 2);
  assert.equal(report.staleness.anchored_rows, 3);
});
